CREATE TYPE "MessageStatus" AS ENUM ('NEW','READ','REPLIED');
CREATE TYPE "ApplicationStatus" AS ENUM ('NEW','REVIEWING','APPROVED','DECLINED');
CREATE TABLE "AdminUser" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AdminUser_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email");
CREATE TABLE "SiteSettings" ("id" INTEGER NOT NULL DEFAULT 1,"phone" TEXT NOT NULL,"secondaryPhone" TEXT,"email" TEXT NOT NULL,"location" TEXT NOT NULL,"facebook" TEXT,"instagram" TEXT,"x" TEXT,"linkedin" TEXT,"youtube" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SiteSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ContactMessage" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"subject" TEXT,"message" TEXT NOT NULL,"status" "MessageStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContactMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NewsletterSubscriber" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "NewsletterSubscriber_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "NewsletterSubscriber_email_key" ON "NewsletterSubscriber"("email");
CREATE TABLE "VolunteerApplication" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"interest" TEXT NOT NULL,"availability" TEXT,"message" TEXT,"status" "ApplicationStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VolunteerApplication_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SponsorEnquiry" ("id" TEXT NOT NULL,"fullName" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"country" TEXT,"city" TEXT,"preferredContact" TEXT,"sponsorshipPreference" TEXT,"message" TEXT,"consent" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SponsorEnquiry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GalleryItem" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"imageUrl" TEXT NOT NULL,"description" TEXT,"category" TEXT,"published" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GalleryItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NewsPost" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"excerpt" TEXT,"body" TEXT NOT NULL,"imageUrl" TEXT,"published" BOOLEAN NOT NULL DEFAULT false,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "NewsPost_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "NewsPost_slug_key" ON "NewsPost"("slug");